@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="_content" @bind:event="oninput" rows="15" style="width:100%"></textarea>

<div style="margin-top:0.5rem; display:flex; gap:0.5rem; align-items:center;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSavedAt is not null)
    {
        <span>Last saved at @_lastSavedAt</span>
    }
</div>

@code {
    private string _content = string.Empty;
    private string? _lastSavedAt;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;
    private Timer? _autoSaveTimer;
    private string _lastSavedContent = string.Empty;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync(_dotNetRef);

            var saved = await _interop.LoadAsync();
            if (saved is not null)
            {
                _content = saved;
                _lastSavedContent = saved;
                StateHasChanged();
            }

            _autoSaveTimer = new Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    if (_content != _lastSavedContent)
                    {
                        await SaveAsync();
                        StateHasChanged();
                    }
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    private async Task SaveNowAsync() => await SaveAsync();

    private async Task SaveAsync()
    {
        if (_interop is not null)
        {
            await _interop.SaveAsync(_content);
            _lastSavedContent = _content;
            _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
        }
    }

    private async Task ClearAsync()
    {
        _content = string.Empty;
        _lastSavedContent = string.Empty;
        _lastSavedAt = null;
        if (_interop is not null)
            await _interop.ClearAsync();
    }

    [JSInvokable]
    public bool HasUnsavedChanges() => _content != _lastSavedContent;

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
            await _autoSaveTimer.DisposeAsync();

        try
        {
            if (_interop is not null)
                await _interop.DisposeAsync();
        }
        catch (JSDisconnectedException) { }

        _dotNetRef?.Dispose();
    }
}

const STORAGE_KEY = 'notepad-content';
const HAS_UNSAVED_CHANGES = 'HasUnsavedChanges';

let dotNetRef = null;

function beforeUnloadHandler(e) {
    if (dotNetRef) {
        // Synchronous check isn't possible with async interop,
        // so we use a synchronous JS-side approach instead.
        // We rely on the dotNetRef callback for the check.
    }
    // For beforeunload, we need a synchronous check.
    // We'll track dirty state from JS side.
    if (isDirty) {
        e.preventDefault();
        e.returnValue = '';
    }
}

let isDirty = false;

export function initialize(dotNetReference) {
    dotNetRef = dotNetReference;
    window.addEventListener('beforeunload', beforeUnloadHandler);
